{"status":"candidate","chosen_option":"single_pass","assumptions":["Python 3 is an acceptable implementation language.","The input contains n parseable signed integers."],"observations":[{"statement":"The task asks for the number of maximal consecutive runs among n signed integers.","source_ids":["task"]},{"statement":"The examples show one run for a single value and four runs for 2, 1, 1, 2, -2, -2.","source_ids":["public1","public2"]}],"artifact":{"code":"import sys

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
values = data[1:1 + n]
runs = 1
for i in range(1, n):
    if values[i] != values[i - 1]:
        runs += 1
print(runs)"}}
